 79→function tokenize(term: string): string[] {
 80→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
 81→}
 82→
 83→function tokenOverlap(a: string, b: string): number {
 84→  const tokensA = tokenize(a);
 85→  const tokensB = tokenize(b);
 86→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
 87→  const setB = new Set(tokensB);
 88→  const matched = tokensA.filter(t => setB.has(t)).length;
 89→  return matched / Math.max(tokensA.length, tokensB.length);
 90→}
 91→
 92→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
 93→  const normalizedJd = normalizeSkill(jdTerm);
 94→  for (const rt of resumeTerms) {
 95→    const normalizedResume = normalizeSkill(rt);
 96→    // Exact match after normalization
 97→    if (normalizedJd === normalizedResume) return true;
 98→    // Substring containment (original behavior)
 99→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
100→    // Token overlap (e.g. "machine learning" vs "ml engineering" after synonym expansion)
101→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
102→  }
103→  return false;
104→}
