811→// ── PDF text extraction fallback ───────────────────────────────
812→function extractPdfText(bytes: Uint8Array): string {
813→  const raw = new TextDecoder("latin1").decode(bytes);
814→  const textChunks: string[] = [];
815→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
816→  let block;
817→  while ((block = btEtRegex.exec(raw)) !== null) {
818→    const parenRegex = /\(([^)]*)\)/g;
819→    let match;
820→    while ((match = parenRegex.exec(block[1])) !== null) {
821→      const decoded = match[1]
822→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
823→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
824→      if (decoded.trim()) textChunks.push(decoded);
825→    }
826→  }
827→  if (textChunks.join(" ").trim().length < 200) {
828→    const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
829→    let sm;
830→    while ((sm = streamRegex.exec(raw)) !== null) {
831→      const readable = sm[1].replace(/[^\x20-\x7E\n\r\t]/g, " ").replace(/\s+/g, " ").trim();
832→      if (readable.length > 50) textChunks.push(readable);
833→    }
834→  }
835→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 10000);
836→}
